    public Person addAlias(String sheetId, String user, long personId, String alias) {
        sheetRows.lockById(sheetId);
        Person person = get(sheetId, personId);
        String trimmed = alias == null ? "" : alias.trim();
        if (trimmed.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Give an alias");
        }
        if (inUse(sheetId, trimmed, null)) {
            throw nameInUse();
        }
        person.addAlias(trimmed);
        people.flush();
        events.publishEvent(new PersonAliasAdded(sheetId, user, person.getName(), trimmed));
        return person;
    }

    /**
     * A person found by {@link #search}: their sheet, name, grade in force on their sheet's today and due-total
     * as shown ({@code n/a} when none).
     */
    public record Found(String sheetId, String name, String grade, String dueTotal) {
    }

    /**
     * Every person on a sheet of the sheet's tree (see {@link SheetService#tree}) whose name or an alias
     * contains the text, compared without regard to case (blank: everyone): the sheet's own people first in
     * list order, then the other sheets' by sheet id, each in its list order.
     */
    @Transactional(readOnly = true)
    public List<Found> search(String sheetId, String text) {
        String key = key(text == null ? "" : text.trim());
        List<String> others = new ArrayList<>(sheets.tree(sheetId));
        others.remove(sheetId);
        Collections.sort(others);
        List<String> order = new ArrayList<>(List.of(sheetId));
        order.addAll(others);
        List<Found> found = new ArrayList<>();
        for (String sheet : order) {
            Map<Long, Rollup.PersonFigures> figures = rollup.figures(sheet).people();
            LocalDate today = sheets.today(sheet);
            for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheet)) {
                if (names(p).stream().anyMatch(n -> n.contains(key))) {
                    Rollup.PersonFigures f = figures.get(p.getId());
                    found.add(new Found(sheet, p.getName(), p.gradeOn(today), f == null ? "n/a" : f.dueTotal()));
                }
            }
        }
        return found;
    }

    /**
     * Whether a person on a sheet of the sheet's tree (see {@link SheetService#tree}), other than the one with
     * the id (none: any), has the name or alias, compared without regard to case.
     */
    @Transactional(readOnly = true)
    public boolean inUse(String sheetId, String name, Long exceptId) {
        String key = key(name);
        return people.findBySheetIdIn(sheets.tree(sheetId)).stream()
                .filter(p -> !p.getId().equals(exceptId))
                .anyMatch(p -> names(p).contains(key));
    }

    /**
     * The ids of the people on the sheet who clash: whose name or an alias another person on a sheet of the
     * sheet's tree also has, compared without regard to case. People who clashed before names became unique
     * across a tree keep their names; each edit of them is refused until they no longer clash.
     */
    @Transactional(readOnly = true)
    public Set<Long> clashing(String sheetId) {
        Map<String, Set<Long>> holders = new HashMap<>();
        for (Person p : people.findBySheetIdIn(sheets.tree(sheetId))) {
            for (String name : names(p)) {
                holders.computeIfAbsent(name, n -> new HashSet<>()).add(p.getId());
            }
        }
        Set<Long> clashing = new HashSet<>();
        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            if (names(p).stream().anyMatch(n -> holders.getOrDefault(n, Set.of()).stream()
                    .anyMatch(id -> !id.equals(p.getId())))) {
                clashing.add(p.getId());
            }
        }
        return clashing;
    }

    /** Whether the person clashes (see {@link #clashing(String)}). */
    @Transactional(readOnly = true)
    public boolean clashing(String sheetId, Person person) {
        return inUse(sheetId, person.getName(), person.getId())
                || person.getAliases().stream().anyMatch(alias -> inUse(sheetId, alias, person.getId()));
    }
package net.officefloor.hq.app.claim;

/**
 * A claim's status: it starts as DRAFT, is opened (OPEN) and then settled (SETTLED); a clerk settling
 * one above the clerk limit leaves it PENDING until a steward approves it (SETTLED) or rejects it (back to
 * OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID), and a
 * steward may void a SETTLED one within 7 days of its settlement. A DRAFT can be DELETED, and restored to a DRAFT on
 * the sheet's today it was deleted. A claim whose due is above the sheet's review threshold goes to REVIEW
 * instead of OPEN when opened, until a steward reviews it (OPEN); a REVIEW claim can be voided. Only OPEN,
 * PENDING and SETTLED claims count toward what is claimed.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether the claim counts toward claimed, due-total and every total. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether the claim is still to be paid: OPEN or PENDING. */
    public boolean unpaid() {
        return this == OPEN || this == PENDING;
    }

    /**
     * Whether a claim in this status may be moved to the given one by opening, settling or voiding it; a
     * PENDING claim leaves PENDING only by being approved, rejected or voided, and a REVIEW claim REVIEW only
     * by being reviewed or voided.
     */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case PENDING, SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
            case DRAFT, DELETED, REVIEW -> false;
        };
    }
}

